// OCR router with a confidence-gated handwriting fallback
// build {{sim.sessionId}}
import { handOcr, printOcr, type OcrResult } from './engines';

export const FALLBACK_BELOW = 0.6;

export async function recognise(page: Uint8Array): Promise<OcrResult> {
  const printed = await printOcr(page);
  if (printed.confidence >= FALLBACK_BELOW) return printed;
  const hand = await handOcr(page);
  return hand.confidence > printed.confidence ? hand : printed;
}

// OCR router tests
// build {{sim.sessionId}}
import { expect, it } from 'vitest';
import { FALLBACK_BELOW } from '../../src/ocr/router';

it('falls back to the handwriting engine below 0.6 confidence', () => {
  expect(FALLBACK_BELOW).toBe(0.6);
});
